-- name: GetPlatformSessionPolicy :one
SELECT idle_seconds,absolute_seconds,version,jsonb_build_object('failed_login_attempts',p.failed_login_attempts,'failure_window_seconds',p.failure_window_seconds,'lockout_seconds',p.lockout_seconds,'minimum_password_bytes',p.minimum_password_bytes,'password_reset_seconds',p.password_reset_seconds,'allow_multiple_sessions',p.allow_multiple_sessions,'admin_idle_seconds',p.admin_idle_seconds,'admin_absolute_seconds',p.admin_absolute_seconds,'step_up_seconds',p.step_up_seconds)::jsonb AS security FROM platform_settings.session_policy p WHERE id=true;
-- name: LockPlatformSessionPolicy :one
SELECT idle_seconds,absolute_seconds,version,jsonb_build_object('failed_login_attempts',p.failed_login_attempts,'failure_window_seconds',p.failure_window_seconds,'lockout_seconds',p.lockout_seconds,'minimum_password_bytes',p.minimum_password_bytes,'password_reset_seconds',p.password_reset_seconds,'allow_multiple_sessions',p.allow_multiple_sessions,'admin_idle_seconds',p.admin_idle_seconds,'admin_absolute_seconds',p.admin_absolute_seconds,'step_up_seconds',p.step_up_seconds)::jsonb AS security FROM platform_settings.session_policy p WHERE id=true FOR UPDATE;
-- name: UpdatePlatformSessionPolicy :execrows
UPDATE platform_settings.session_policy SET idle_seconds=sqlc.arg(idle_seconds),absolute_seconds=sqlc.arg(absolute_seconds),failed_login_attempts=(sqlc.arg(security)::jsonb->>'failed_login_attempts')::integer,failure_window_seconds=(sqlc.arg(security)::jsonb->>'failure_window_seconds')::integer,lockout_seconds=(sqlc.arg(security)::jsonb->>'lockout_seconds')::integer,minimum_password_bytes=(sqlc.arg(security)::jsonb->>'minimum_password_bytes')::integer,password_reset_seconds=(sqlc.arg(security)::jsonb->>'password_reset_seconds')::integer,allow_multiple_sessions=(sqlc.arg(security)::jsonb->>'allow_multiple_sessions')::boolean,admin_idle_seconds=(sqlc.arg(security)::jsonb->>'admin_idle_seconds')::integer,admin_absolute_seconds=(sqlc.arg(security)::jsonb->>'admin_absolute_seconds')::integer,step_up_seconds=COALESCE(NULLIF((sqlc.arg(security)::jsonb->>'step_up_seconds')::integer,0),step_up_seconds),version=version+1,updated_at=sqlc.arg(at)::timestamptz,updated_by=sqlc.arg(actor_id)::uuid WHERE id=true AND version=sqlc.arg(expected_version);
-- name: GetPlatformSessionPolicyCommand :one
SELECT request_hash,result_version FROM platform_settings.session_policy_commands WHERE actor_id=sqlc.arg(actor_id)::uuid AND key_hash=sqlc.arg(key_hash)::bytea;
-- name: InsertPlatformSessionPolicyCommand :exec
INSERT INTO platform_settings.session_policy_commands(actor_id,key_hash,request_hash,result_version) VALUES(sqlc.arg(actor_id)::uuid,sqlc.arg(key_hash)::bytea,sqlc.arg(request_hash)::bytea,sqlc.arg(result_version));
-- name: AppendPlatformSessionPolicyAudit :exec
