VALUES(sqlc.arg(id)::uuid,NULL,sqlc.arg(actor_id)::uuid,'PlatformSessionPolicyUpdated','platform_session_policy','00000000-0000-4000-8000-000000000038'::uuid,sqlc.arg(at)::timestamptz,'SUCCEEDED',sqlc.arg(correlation_id)::uuid,jsonb_build_object('version',sqlc.arg(version)::bigint,'sessions_revoked',sqlc.arg(revoked)::bigint,'changes',sqlc.arg(changes)::jsonb),1,sqlc.arg(at)::timestamptz);
